import{z as n,x as h,o as e,c as B,q as t,j as E,D as s,d as i,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"图形 Lasso 精度矩阵","description":"","frontmatter":{"title":"图形 Lasso 精度矩阵","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/glasso.md","filePath":"quant/glasso.md","lastUpdated":1791413859000}'),A={name:"quant/glasso.md"};function d(p,a,m,T,g,c){const o=h("Mermaid");return e(),B("div",null,[a[2]||(a[2]=t('<h1 id="图形-lasso-精度矩阵" tabindex="-1">图形 Lasso 精度矩阵 <a class="header-anchor" href="#图形-lasso-精度矩阵" aria-label="Permalink to &quot;图形 Lasso 精度矩阵&quot;">​</a></h1><div class="epigraph"><p>高斯图模型里，精度矩阵的零意味着条件独立；用 L1 惩罚似然去估计一张稀疏的精度图，比直接把样本协方差求逆更适合高维、且需要可解释偏相关的场合。</p><footer>—— Friedman, Hastie and Tibshirani, Sparse inverse covariance estimation with the graphical lasso, Biostatistics, 2008</footer></div><p>组合优化真正调用的常常是 \\(\\Sigma^{-1}\\)，不是 \\(\\Sigma\\)。样本协方差 \\(S\\) 病态时，逆会放大噪声；<a href="/quant/ledoit-wolf">Ledoit–Wolf</a> 从协方差一侧把 \\(S\\) 拉向简单目标。<a href="/quant/cov-shrinkage">估计误差与收缩</a> 把这条路放在收缩家族里。图形 Lasso（Graphical Lasso, glasso）走另一侧：直接估计精度 \\(\\Theta=\\Sigma^{-1}\\)，并让许多偏相关为零。Friedman、Hastie 与 Tibshirani（2008）给出坐标下降算法，把 Yuan–Lin、Banerjee–El Ghaoui–d&#39;Aspremont 的稀疏精度估计做成可计算的标准件。本篇写精度图的含义、惩罚似然怎么解、以及它在股票上何时比 LW / 因子模型更合适。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多元正态下，\\(\\Theta_{ij}=0\\) 当且仅当 \\(i\\) 与 \\(j\\) 在给定其余变量后独立。偏相关 \\(\\rho^{ij}=-\\Theta_{ij}/\\sqrt{\\Theta_{ii}\\Theta_{jj}}\\) 描述的是净相关：去掉其他资产的线性影响之后还剩多少。这对网络、成对交易的残差结构、以及「谁与谁直接相连」的风险叙事有用。样本精度 \\(S^{-1}\\) 在 \\(N\\approx T\\) 时稠密且吵，几乎每个偏相关都显著，图不可读，组合权重也炸。</p><p><span class="marginnote">「精度矩阵」就是协方差的逆（不是「精确度」的意思）。它的非对角元给出偏相关：剔除所有其他资产的线性影响后，两只股票还剩多少联动。普通相关像「总绑定」，偏相关像「去掉共同朋友后的私交」——网络图的一条边，画的正是后者。</span></p><p>需要一种估计：\\(\\hat\\Theta\\) 正定、许多非对角为零、在高斯似然下不要太差。L1 惩罚把小的偏相关打到零，等价于在图上做边选择。问题是：收益不是正态、有共同因子时精度往往并不稀疏（一个市场因子会让残差精度稀疏、但原始收益精度稠密），惩罚参数 \\(\\rho\\) 选错会得到空图或几乎完全图。</p><h3 id="稀疏的是边-不是特征值" tabindex="-1">稀疏的是边，不是特征值 <a class="header-anchor" href="#稀疏的是边-不是特征值" aria-label="Permalink to &quot;稀疏的是边，不是特征值&quot;">​</a></h3><p>LW 改善的是谱：把散开的特征值推回去。Glasso 改善的是支撑：哪些偏相关允许非零。两者都能让 \\(\\hat\\Sigma\\) 可逆，机制不同。真实若是低秩因子加对角特异，精度是 Sherman–Morrison 意义下的稠密扰动，对原始收益做 glasso 会被迫留下许多小边，或为了稀疏而偏掉因子结构。更干净的顺序往往是：先抽因子，再对残差做 glasso 或对角。不要指望 glasso 自动发现「市场」。</p><p><span class="marginnote">Meinshausen–Bühlmann 的邻域选择对每个节点做 Lasso 回归，再对称化，也是在估精度图。Glasso 用联合似然，保证正定；邻域法更快、正定性要后处理。组合求逆需要正定，优先 glasso 或事后投影。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>高斯对数似然（忽略常数）为 \\(\\log\\det\\Theta-\\mathrm{tr}(S\\Theta)\\)。图形 Lasso 解</p> \\[\\max_{\\Theta\\succ 0}\\ \\log\\det\\Theta-\\mathrm{tr}(S\\Theta)-\\rho\\|\\Theta\\|_{1,\\mathrm{off}}, \\]<p>\\(\\|\\cdot\\|_{1,\\mathrm{off}}\\) 通常不惩罚对角，以免把方差打到零。\\(\\rho\\) 越大图越稀。Friedman 等人用块坐标下降：对每一列把问题化成 Lasso，循环至收敛；这是「glasso」这个名字在软件里的含义。\\(\\rho\\) 用交叉验证（对数似然或样本外最小方差）、信息准则、或稳定性选择。组合场景下，直接用下一期已实现方差选 \\(\\rho\\)，比用高斯似然更贴目标。</p><p>输入 \\(S\\) 可以是样本协方差、EWMA 协方差或稳健协方差。Glasso 不修复厚尾；可以先对收益做稳健相关，再估精度。缺失数据应先补全。得到 \\(\\hat\\Theta\\) 后，\\(\\hat\\Sigma=\\hat\\Theta^{-1}\\) 用于风险；权重若是最小方差，可直接用 \\(\\hat\\Theta\\mathbf{1}\\) 而不显式求逆，数值更好。</p><h3 id="与因子、lw-的叠放" tabindex="-1">与因子、LW 的叠放 <a class="header-anchor" href="#与因子、lw-的叠放" aria-label="Permalink to &quot;与因子、LW 的叠放&quot;">​</a></h3><p>三种正则可以排成栈：因子结构吸收共同运动 \\(\\Sigma=BFB^\\top+\\Delta\\)；若允许残差相关，对残差协方差做 LW 或对残差精度做 glasso；对角 \\(\\Delta\\) 是最强的稀疏（残差图没有边）。股票截面上，残差 glasso 有时能抓到未被行业哑变量写尽的供应链对；边的稳定性必须跨窗口检查，否则是在拟合噪声链。指数增强里，用精度图做「谁可以对冲谁」的候选，再用经济审查删边，比把整个 \\(\\hat\\Theta\\) 当真理更安全。</p><p><span class="marginnote">常见误区：对原始收益直接跑 glasso，再惊叹「发现了全互联网络」。实际上一个共同市场因子就足以让原始精度稠密——每对股票都经由市场间接相连。先剥离因子、再对残差估计，图才可读；否则你画出的多半是「市场因子」的影子，而不是个股之间的直接关系。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>L1 惩罚的机制与回归 Lasso 相同：小系数的最优解在零处有角点。似然项推动 \\(\\Theta\\) 去拟合 \\(S^{-1}\\) 的大方向，惩罚项禁止为拟合噪声偏相关而付出的代价。于是估计的有效自由度变成「边的数量」，而不是 \\(N(N+1)/2\\)。条件数：稀疏正定精度的特征值被惩罚从两侧夹紧，但不像 LW 那样有显式的目标谱。\\(\\rho\\) 过大时 \\(\\hat\\Theta\\) 接近对角，最小方差退回逆波动；\\(\\rho\\) 过小时回到病态的 \\(S^{-1}\\)。</p>',20)),(e(),E(l,null,{default:s(()=>[r(o,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20RHO%7B%22%E6%83%A9%E7%BD%9A%20%CF%81%20%E6%8B%A8%E5%88%B0%E5%A4%9A%E5%A4%A7%22%7D%20--%3E%7C%22%E8%BF%87%E5%A4%A7%22%7C%20Big%5B%22%E5%9B%BE%E6%8E%A5%E8%BF%91%E5%AF%B9%E8%A7%92%EF%BC%9A%E4%B8%80%E6%9D%A1%E8%BE%B9%E9%83%BD%E4%B8%8D%E5%89%A9%22%5D%0A%20%20RHO%20--%3E%7C%22%E9%80%82%E4%B8%AD%22%7C%20Mid%5B%22%E7%9C%9F%E8%BE%B9%E4%BF%9D%E7%95%99%EF%BC%8C%E5%99%AA%E5%A3%B0%E8%BE%B9%E5%BD%92%E9%9B%B6%22%5D%0A%20%20RHO%20--%3E%7C%22%E8%BF%87%E5%B0%8F%22%7C%20Small%5B%22%E5%87%A0%E4%B9%8E%E5%85%A8%E8%BF%9E%E9%80%9A%EF%BC%9A%CE%98%20%E7%97%85%E6%80%81%22%5D%0A%20%20Big%20--%3E%20MV1%5B%22%E6%9C%80%E5%B0%8F%E6%96%B9%E5%B7%AE%E9%80%80%E5%8C%96%E4%B8%BA%E9%80%86%E6%B3%A2%E5%8A%A8%E7%8E%87%22%5D%0A%20%20Small%20--%3E%20MV2%5B%22%E6%9D%83%E9%87%8D%E7%88%86%E7%82%B8%EF%BC%8C%E6%8D%A2%E6%89%8B%E5%A4%B1%E6%8E%A7%22%5D%0A%20%20Mid%20--%3E%20MV3%5B%22%E5%8F%AF%E9%80%86%E4%B8%94%E5%8F%AF%E8%AF%BB%E7%9A%84%E7%B2%BE%E5%BA%A6%E7%9F%A9%E9%98%B5%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">为什么 L1 能把系数打到恰好为零？几何直觉：L1 的约束区域是有尖角的菱形，最优解撞上尖角时对应坐标正好是零；L2 的圆盘没有尖角，几乎不会产生精确的零。glasso 用这种「菱形罚」把小的偏相关干脆判零——选边就是这么完成的。</span></p><p>非高斯时，零精度不再等于条件独立，但偏相关仍是线性净相关。估计器可以当高维逆协方差的稀疏收缩来用，不必坚持图模型的因果解读。MacKenzie 式的警告在这里同样适用：不要把估出来的边当成「传染渠道」的发现，除非在多种 \\(\\rho\\)、多个窗口和经济学约束下重复出现。</p><p><span class="marginnote">精度图的边不是交易信号。两只股票之间稳定的偏相关，可能是共同的未建模行业，而不是可交易的配对。把 glasso 的边拿去自动做配对交易，是把风险估计器误用成 alpha 生成器。</span></p><h3 id="计算与数值" tabindex="-1">计算与数值 <a class="header-anchor" href="#计算与数值" aria-label="Permalink to &quot;计算与数值&quot;">​</a></h3><p>\\(N\\) 到几百时，标准 glasso 可接受；\\(N\\) 上千需要对 \\(\\rho\\) 路径、近似算法或只对残差维做。\\(\\rho\\) 路径上应对 \\(\\Theta\\) 做热启动。对称性：算法应保持 \\(\\Theta\\) 对称正定，浮点误差要用特征值抬升修补。正则化参数若按日重估，边集会跳，组合换手会爆；应对 \\(\\rho\\) 或边集做时间平滑，与风险模型载荷「慢含义、快协方差」的原则一致。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要对未去市场、未去行业的原始收益声称「发现了稀疏信用网络」。不要用全样本 CV 选 \\(\\rho\\) 再报告同一样本的组合表现。不要在 \\(T\\lt N\\) 时把 \\(S\\) 直接送进需要正定 \\(S\\) 的实现而不检查；有的实现内部会处理奇异 \\(S\\)，有的不会。收益的波动聚类会让无条件 glasso 在危机里边数激增——那是体制切换，应用滚动窗或 DCC 一类条件相关再取精度。</p><p>审计：报告 \\(\\rho\\)、边密度、最小特征值、以及与对角/LW/因子模型的样本外方差对比。若 glasso 只在样本内似然赢、样本外最小方差输给 LW，应放弃图叙事。监管与归因需要可命名因子时，<a href="/quant/fundamental-risk-model">基本面风险模型</a> 仍是主模型，glasso 只适合残差层或研究用网络。</p><p><span class="marginnote">惩罚可以只加在预先禁止的边上（先验图）：例如禁止跨市场的边、允许同业边。这比完全数据驱动的稀疏更符合交易约束。无先验的 glasso 在股票上很容易画出无法执行的对冲边。</span></p>',9)),(e(),E(l,null,{default:s(()=>[r(o,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8D%8F%E6%96%B9%E5%B7%AE%20S%22%5D%20--%3E%20GL%5B%22glasso%3A%20max%20logdet%CE%98%20-%20tr(S%CE%98)%20-%20%CF%81%7C%7C%CE%98%7C%7C%E2%82%81%22%5D%0A%20%20RHO%5B%22%E6%83%A9%E7%BD%9A%20%CF%81%22%5D%20--%3E%20GL%0A%20%20GL%20--%3E%20TH%5B%22%E7%A8%80%E7%96%8F%E7%B2%BE%E5%BA%A6%20%CE%98%20%3D%20%CE%A3%E2%81%BB%C2%B9%22%5D%0A%20%20TH%20--%3E%20MV%5B%22%E6%9C%80%E5%B0%8F%E6%96%B9%E5%B7%AE%20w%20%E2%88%9D%20%CE%98%201%22%5D%0A%20%20TH%20--%3E%20G%5B%22%E5%81%8F%E7%9B%B8%E5%85%B3%E5%9B%BE%22%5D%0A%20%20FAC%5B%22%E5%85%88%E6%8A%BD%E5%9B%A0%E5%AD%90%22%5D%20--%3E%20U%5B%22%E6%AE%8B%E5%B7%AE%E5%86%8D%20glasso%22%5D%0A%20%20U%20--%3E%20TH%0A%20%20LW%5B%22Ledoit-Wolf%20%E7%BC%A9%20%CE%A3%22%5D%20--%3E%20CMP%5B%22%E8%B0%B1%E6%94%B6%E7%BC%A9%20vs%20%E8%BE%B9%E7%A8%80%E7%96%8F%22%5D%0A%20%20GL%20--%3E%20CMP%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>图形 Lasso 用 L1 惩罚高斯似然估计稀疏精度矩阵，零元对应（高斯）条件独立 / 偏相关为零。</li><li>Friedman–Hastie–Tibshirani（2008）的块坐标算法是标准实现；\\(\\rho\\) 应用样本外风险目标选择。</li><li>对原始股票收益，因子结构往往使精度不稀疏；更合理的是对残差做 glasso。</li><li>与 LW 互补：一个缩谱，一个选边；两者都服务于可逆的 \\(\\Sigma^{-1}\\)，都不是 alpha。</li><li>出处：Friedman, Hastie and Tibshirani, <em>Biostatistics</em>, 2008；Yuan and Lin, <em>Biometrika</em>, 2007；Banerjee, El Ghaoui and d&#39;Aspremont, <em>JMLR</em>, 2008；邻域选择见 Meinshausen and Bühlmann, <em>Annals of Statistics</em>, 2006。收缩总论见 <a href="/quant/cov-shrinkage">估计误差与收缩</a>。</li></ul>',2))])}const u=n(A,[["render",d]]);export{_ as __pageData,u as default};
